// Build full JSON for te, kn, bn by copying Japanese structure and overriding nav/common/home keys
for (const [code, s] of Object.entries(scriptLangs)) {
  const base = JSON.parse(JSON.stringify(minimal.ja));
  // Override navbar
  base.navbar = {...base.navbar, ...s.nav};
  // Override footer tagline
  base.footer.tagline = s.ftag;
  // Override common
  base.common = {...base.common, ...s.cm};
  // Override home top-level strings
  base.home = {...base.home,
    tagline:s.hTagline,titlePrefix:s.hPrefix,titleGlow:s.hGlow,subtitle:s.hSub,
    exploreBtn:s.cm.applyNow,learnBtn:s.cm.learnMore
  };
  // Override dashboard
  base.dashboard.welcome = s.dashWelcome;
  base.dashboard.status = s.dashStatus;
  base.dashboard.noName = s.dashNoName;
  // Override errors
  base.errors['404'].title = s.err404;
  base.errors['general'].title = s.errGen;
  // Override auth sign-in/sign-up titles
  base.auth.signIn.title = s.siTitle;
  base.auth.signUp.title = s.suTitle;
  // article content stays English (fallback works)
  fs.writeFileSync(path.join(dir, `${code}.json`), JSON.stringify(base, null, 2), 'utf8');
  console.log(`✓  ${code}.json`);
}

// Write Japanese
fs.writeFileSync(path.join(dir, 'ja.json'), JSON.stringify(minimal.ja, null, 2), 'utf8');
